#ifndef KERNEL_H
#define KERNEL_H

#include <ap_fixed.h>
#include <ap_int.h>
#include <hls_math.h>

// ---------------------------------------------------------------------------
// Type definitions derived from params.yaml
// bits_per_component = bits + signed
// ap_fixed<bpc, bpc - fraction>
// ---------------------------------------------------------------------------

// Input 0: acm / A  — complex, bits=22, signed=1, fraction=0
//   bpc = 23, integer_bits = 23 - 0 = 23
typedef ap_fixed<23, 23> in0_scalar_t;
struct in0_t { in0_scalar_t re, im; };
#define DIM_IN0_0 10
#define DIM_IN0_1 10

// Input 1: max_iter — real, bits=16, signed=0, fraction=0
//   bpc = 16, integer_bits = 16 - 0 = 16
typedef ap_uint<16> in1_t;

// Output 0: eigenvalues — complex, bits=22, signed=1, fraction=0
//   bpc = 23, integer_bits = 23
typedef ap_fixed<23, 23> out0_scalar_t;
struct out0_t { out0_scalar_t re, im; };
#define DIM_OUT0_0 10

// Output 1: eigenvectors — complex, bits=22, signed=1, fraction=20
//   bpc = 23, integer_bits = 23 - 20 = 3
typedef ap_fixed<23, 3> out1_scalar_t;
struct out1_t { out1_scalar_t re, im; };
#define DIM_OUT1_0 10
#define DIM_OUT1_1 10

// Output 2: ite — real, bits=16, signed=0, fraction=0
//   bpc = 16, integer_bits = 16
typedef ap_uint<16> out2_t;

// ---------------------------------------------------------------------------
// Top-level kernel declaration
// ---------------------------------------------------------------------------
void kernel_top(
    in0_t  in0[DIM_IN0_0][DIM_IN0_1],
    in1_t  in1,
    out0_t out0[DIM_OUT0_0],
    out1_t out1[DIM_OUT1_0][DIM_OUT1_1],
    out2_t *out2
);

#endif // KERNEL_H

=== FILE: hls/kernel.cpp ===
#include "kernel.h"
#include <hls_math.h>

// ---------------------------------------------------------------------------
// Internal precision for floating-point intermediate computation
// We use double-width fixed-point internally to preserve accuracy through
// the trigonometric / rotation operations.
// ---------------------------------------------------------------------------
typedef ap_fixed<48, 24> calc_t;   // signed, enough headroom + fraction

// ---------------------------------------------------------------------------
// Helper: complex multiply  (a + jb)(c + jd)
// ---------------------------------------------------------------------------
static void cmul(calc_t ar, calc_t ai,
                 calc_t br, calc_t bi,
                 calc_t &cr, calc_t &ci)
{
#pragma HLS INLINE
    cr = ar * br - ai * bi;
    ci = ar * bi + ai * br;
}

// ---------------------------------------------------------------------------
// Helper: magnitude squared  |a+jb|^2
// ---------------------------------------------------------------------------
static calc_t cabs2(calc_t ar, calc_t ai)
{
#pragma HLS INLINE
    return ar * ar + ai * ai;
}

// ---------------------------------------------------------------------------
// Helper: magnitude  |a+jb|
// ---------------------------------------------------------------------------
static calc_t cabs(calc_t ar, calc_t ai)
{
#pragma HLS INLINE
    return hls::sqrt((double)(ar * ar + ai * ai));
}

// ---------------------------------------------------------------------------
// Top function
// ---------------------------------------------------------------------------
void kernel_top(
    in0_t  in0[DIM_IN0_0][DIM_IN0_1],
    in1_t  in1,
    out0_t out0[DIM_OUT0_0],
    out1_t out1[DIM_OUT1_0][DIM_OUT1_1],
    out2_t *out2)
{
#pragma HLS INTERFACE ap_ctrl_hs port=return
#pragma HLS INTERFACE ap_memory port=in0
#pragma HLS INTERFACE ap_memory port=out0
#pragma HLS INTERFACE ap_memory port=out1

    const int N = 10;

    // -----------------------------------------------------------------------
    // Working arrays in internal precision (real and imag separately)
    // -----------------------------------------------------------------------
    calc_t Ar[N][N], Ai[N][N];   // working copy of A
    calc_t Vr[N][N], Vi[N][N];   // eigenvector matrix (starts as identity)

    // Copy input into working arrays
    INIT_COPY_I:
    for (int i = 0; i < N; i++) {
#pragma HLS UNROLL
        INIT_COPY_J:
        for (int j = 0; j < N; j++) {
#pragma HLS UNROLL
            Ar[i][j] = (calc_t)(double)in0[i][j].re;
            Ai[i][j] = (calc_t)(double)in0[i][j].im;
        }
    }

    // V = eye(N)
    INIT_V_I:
    for (int i = 0; i < N; i++) {
#pragma HLS UNROLL
        INIT_V_J:
        for (int j = 0; j < N; j++) {
#pragma HLS UNROLL
            Vr[i][j] = (i == j) ? (calc_t)1 : (calc_t)0;
            Vi[i][j] = (calc_t)0;
        }
    }

    int max_iter = (int)(unsigned)in1;
    int final_z  = 0;

    // -----------------------------------------------------------------------
    // Jacobi iteration
    // -----------------------------------------------------------------------
    ITER_LOOP:
    for (int z = 0; z < 512; z++) {
#pragma HLS LOOP_TRIPCOUNT min=1 max=512

        if (z >= max_iter) break;

        // -------------------------------------------------------------------
        // Find (p,q) with largest |A[i,j]| for i<j
        // -------------------------------------------------------------------
        calc_t off_max = (calc_t)0;
        int p = 0, q = 1;

        FIND_P_I:
        for (int i = 0; i < N; i++) {
            FIND_P_J:
            for (int j = i + 1; j < N; j++) {
                calc_t mag = cabs(Ar[i][j], Ai[i][j]);
                if (mag > off_max) {
                    off_max = mag;
                    p = i;
                    q = j;
                }
            }
        }

        // Convergence check: 1e-8 threshold
        if (off_max < (calc_t)1e-8) {
            final_z = z;
            break;
        }
        final_z = z;

        // -------------------------------------------------------------------
        // Compute rotation parameters
        // a_pp, a_qq, a_pq
        // -------------------------------------------------------------------
        calc_t app_r = Ar[p][p];  // real diagonal — imaginary should be ~0
        calc_t aqq_r = Ar[q][q];
        calc_t apq_r = Ar[p][q];
        calc_t apq_i = Ai[p][q];

        calc_t abs_apq = cabs(apq_r, apq_i);

        // theta = 0.5 * arctan(2*|a_pq| / (a_pp - a_qq))
        calc_t denom = app_r - aqq_r;
        double theta_d;
        if ((double)denom == 0.0) {
            theta_d = 3.14159265358979323846 / 4.0;  // pi/4
        } else {
            theta_d = 0.5 * hls::atan((double)(2.0 * abs_apq) / (double)denom);
        }
        calc_t cos_theta = (calc_t)hls::cos(theta_d);
        calc_t sin_theta = (calc_t)hls::sin(theta_d);

        // phi = -angle(a_pq)  =>  exp(-j*phi) = a_pq / |a_pq|
        // exp(+j*phi) = conj(a_pq) / |a_pq|
        calc_t exp_neg_phi_r, exp_neg_phi_i;   // exp(-j*phi)
        calc_t exp_pos_phi_r, exp_pos_phi_i;   // exp(+j*phi)

        if ((double)abs_apq < 1e-30) {
            exp_neg_phi_r = (calc_t)1;  exp_neg_phi_i = (calc_t)0;
            exp_pos_phi_r = (calc_t)1;  exp_pos_phi_i = (calc_t)0;
        } else {
            calc_t inv_abs = (calc_t)(1.0 / (double)abs_apq);
            exp_neg_phi_r =  apq_r * inv_abs;   //  re(a_pq)/|a_pq|
            exp_neg_phi_i =  apq_i * inv_abs;   //  im(a_pq)/|a_pq|  => this is exp(-j*phi) since phi=-angle(a_pq)
            // Actually angle(a_pq) = atan2(im, re), phi = -angle(a_pq)
            // exp(-j*phi) = exp(j*angle(a_pq)) = a_pq/|a_pq|  ✓
            exp_pos_phi_r =  apq_r * inv_abs;   //  conj of exp(-j*phi) ... 
            exp_pos_phi_i = -apq_i * inv_abs;   //  = exp(+j*phi)
            // Swap: exp(-j*phi) = a_pq/|a_pq|, exp(+j*phi) = conj(a_pq)/|a_pq|
            // Let's redo clearly:
            // phi = -angle(a_pq)
            // exp(-j*phi) = exp(j*angle(a_pq)) = (re+j*im)/|a_pq|
            exp_neg_phi_r =  apq_r * inv_abs;
            exp_neg_phi_i =  apq_i * inv_abs;
            // exp(+j*phi) = exp(-j*angle(a_pq)) = conj(a_pq)/|a_pq|
            exp_pos_phi_r =  apq_r * inv_abs;
            exp_pos_phi_i = -apq_i * inv_abs;
        }

        // U[p,p] = cos_theta,                  U[p,q] = sin_theta*exp(-j*phi)
        // U[q,p] = sin_theta*exp(+j*phi),      U[q,q] = -cos_theta
        // All other diagonal entries = 1, off-diagonal = 0

        calc_t Upp_r = cos_theta,  Upp_i = (calc_t)0;
        calc_t Upq_r, Upq_i;
        calc_t Uqp_r, Uqp_i;
        calc_t Uqq_r = -cos_theta, Uqq_i = (calc_t)0;

        Upq_r = sin_theta * exp_neg_phi_r;
        Upq_i = sin_theta * exp_neg_phi_i;
        Uqp_r = sin_theta * exp_pos_phi_r;
        Uqp_i = sin_theta * exp_pos_phi_i;

        // -------------------------------------------------------------------
        // A ← U^H * A * U
        // We do this in two passes: B = U^H * A, then A = B * U
        // U^H[p,p] = cos_theta,               U^H[p,q] = conj(Uqp) = sin*exp(-j*phi)
        // U^H[q,p] = conj(Upq) = sin*exp(+j*phi), U^H[q,q] = -cos_theta
        // (U is unitary and the structure makes U^H easy to compute)
        // -------------------------------------------------------------------

        // Uh[p,p] = conj(U[p,p]) = cos_theta
        // Uh[p,q] = conj(U[q,p]) = conj(Uqp)
        // Uh[q,p] = conj(U[p,q]) = conj(Upq)
        // Uh[q,q] = conj(U[q,q]) = -cos_theta

        calc_t Uhpp_r =  cos_theta,   Uhpp_i = (calc_t)0;
        calc_t Uhpq_r =  Uqp_r,       Uhpq_i = -Uqp_i;   // conj(Uqp)
        calc_t Uhqp_r =  Upq_r,       Uhqp_i = -Upq_i;   // conj(Upq)
        calc_t Uhqq_r = -cos_theta,   Uhqq_i = (calc_t)0;

        // ---- Pass 1: B = U^H * A  (only rows p and q change) ----
        calc_t Br[N][N], Bi[N][N];

        // Copy all rows first
        PASS1_COPY_I:
        for (int i = 0; i < N; i++) {
#pragma HLS UNROLL
            PASS1_COPY_J:
            for (int j = 0; j < N; j++) {
#pragma HLS UNROLL
                Br[i][j] = Ar[i][j];
                Bi[i][j] = Ai[i][j];
            }
        }

        // Update row p and row q of B
        PASS1_J:
        for (int j = 0; j < N; j++) {
#pragma HLS UNROLL
            calc_t t1r, t1i, t2r, t2i;
            // B[p,j] = Uh[p,p]*A[p,j] + Uh[p,q]*A[q,j]
            cmul(Uhpp_r, Uhpp_i, Ar[p][j], Ai[p][j], t1r, t1i);
            cmul(Uhpq_r, Uhpq_i, Ar[q][j], Ai[q][j], t2r, t2i);
            Br[p][j] = t1r + t2r;  Bi[p][j] = t1i + t2i;

            // B[q,j] = Uh[q,p]*A[p,j] + Uh[q,q]*A[q,j]
            cmul(Uhqp_r, Uhqp_i, Ar[p][j], Ai[p][j], t1r, t1i);
            cmul(Uhqq_r, Uhqq_i, Ar[q][j], Ai[q][j], t2r, t2i);
            Br[q][j] = t1r + t2r;  Bi[q][j] = t1i + t2i;
        }

        // ---- Pass 2: A = B * U  (only cols p and q change) ----
        // Copy B -> A first
        PASS2_COPY_I:
        for (int i = 0; i < N; i++) {
#pragma HLS UNROLL
            PASS2_COPY_J:
            for (int j = 0; j < N; j++) {
#pragma HLS UNROLL
                Ar[i][j] = Br[i][j];
                Ai[i][j] = Bi[i][j];
            }
        }

        // Update col p and col q
        PASS2_I:
        for (int i = 0; i < N; i++) {
#pragma HLS UNROLL
            calc_t t1r, t1i, t2r, t2i;
            // A[i,p] = B[i,p]*U[p,p] + B[i,q]*U[q,p]
            cmul(Br[i][p], Bi[i][p], Upp_r, Upp_i, t1r, t1i);
            cmul(Br[i][q], Bi[i][q], Uqp_r, Uqp_i, t2r, t2i);
            Ar[i][p] = t1r + t2r;  Ai[i][p] = t1i + t2i;

            // A[i,q] = B[i,p]*U[p,q] + B[i,q]*U[q,q]
            cmul(Br[i][p], Bi[i][p], Upq_r, Upq_i, t1r, t1i);
            cmul(Br[i][q], Bi[i][q], Uqq_r, Uqq_i, t2r, t2i);
            Ar[i][q] = t1r + t2r;  Ai[i][q] = t1i + t2i;
        }

        // Force symmetry zeros
        Ar[p][q] = (calc_t)0;  Ai[p][q] = (calc_t)0;
        Ar[q][p] = (calc_t)0;  Ai[q][p] = (calc_t)0;

        // ---- V = V * U  (only cols p and q change) ----
        calc_t Vr_cp[N], Vi_cp[N];   // saved col p
        calc_t Vr_cq[N], Vi_cq[N];  // saved col q

        SAVE_V_I:
        for (int i = 0; i < N; i++) {
#pragma HLS UNROLL
            Vr_cp[i] = Vr[i][p];  Vi_cp[i] = Vi[i][p];
            Vr_cq[i] = Vr[i][q];  Vi_cq[i] = Vi[i][q];
        }

        UPDATE_V_I:
        for (int i = 0; i < N; i++) {
#pragma HLS UNROLL
            calc_t t1r, t1i, t2r, t2i;
            // V[i,p] = V_old[i,p]*U[p,p] + V_old[i,q]*U[q,p]
            cmul(Vr_cp[i], Vi_cp[i], Upp_r, Upp_i, t1r, t1i);
            cmul(Vr_cq[i], Vi_cq[i], Uqp_r, Uqp_i, t2r, t2i);
            Vr[i][p] = t1r + t2r;  Vi[i][p] = t1i + t2i;

            // V[i,q] = V_old[i,p]*U[p,q] + V_old[i,q]*U[q,q]
            cmul(Vr_cp[i], Vi_cp[i], Upq_r, Upq_i, t1r, t1i);
            cmul(Vr_cq[i], Vi_cq[i], Uqq_r, Uqq_i, t2r, t2i);
            Vr[i][q] = t1r + t2r;  Vi[i][q] = t1i + t2i;
        }
    }

    // -----------------------------------------------------------------------
    // Write outputs
    // -----------------------------------------------------------------------

    // out0: eigenvalues = diag(A)
    OUT0_LOOP:
    for (int i = 0; i < N; i++) {
#pragma HLS UNROLL
        out0[i].re = (out0_scalar_t)(double)Ar[i][i];
        out0[i].im = (out0_scalar_t)(double)Ai[i][i];
    }

    // out1: eigenvectors = V
    OUT1_I:
    for (int i = 0; i < N; i++) {
#pragma HLS UNROLL
        OUT1_J:
        for (int j = 0; j < N; j++) {
#pragma HLS UNROLL
            out1[i][j].re = (out1_scalar_t)(double)Vr[i][j];
            out1[i][j].im = (out1_scalar_t)(double)Vi[i][j];
        }
    }

    // out2: number of iterations (z at break or end)
    *out2 = (out2_t)final_z;
}
